import sys
import json
import collections

# Parse input parameters from stdin
input_data = json.loads(sys.stdin.read())
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def find_path():
    width, height = 30, 30
    if map_id == "0_218": # North is 40x36
        width, height = 40, 36

    impassable_ground = set()
    plateau_tiles = set()
    stairs = {} # maps (x, y, from_level) to (nx, ny, to_level)

    # Define collisions and plateaus for each Safari map:
    if map_id == "0_217": # Safari Zone East
        for x in range(30):
            impassable_ground.add((x, 20))
            impassable_ground.add((x, 25))
        for x in range(5, 10):
            for y in range(21, 24):
                impassable_ground.add((x, y))
        for x in range(11, 23):
            for y in range(12, 21):
                if 16 <= x <= 19 and 16 <= y <= 17:
                    continue
                plateau_tiles.add((x, y))
        for x in range(11, 25):
            for y in range(4, 7):
                plateau_tiles.add((x, y))

        # Stair transitions:
        stairs[(20, 21, 0)] = (20, 20, 1)
        stairs[(20, 20, 1)] = (20, 21, 0)
        stairs[(12, 21, 0)] = (12, 20, 1)
        stairs[(12, 20, 1)] = (12, 21, 0)
        stairs[(12, 8, 0)] = (12, 6, 1)
        stairs[(12, 6, 1)] = (12, 8, 0)
        stairs[(17, 8, 0)] = (17, 6, 1)
        stairs[(17, 6, 1)] = (17, 8, 0)

    elif map_id == "0_218": # Safari Zone North
        for x in range(10, 20):
            impassable_ground.add((x, 34))
        for y in range(11, 20):
            impassable_ground.add((16, y))
        for x in range(18, 25):
            for y in range(20, 23):
                plateau_tiles.add((x, y))
        for y in range(20, 23):
            impassable_ground.add((25, y))
        stairs[(22, 23, 0)] = (22, 22, 1)
        stairs[(22, 22, 1)] = (22, 23, 0)

    elif map_id == "0_219": # Safari Zone West
        # Main plateau vertical section: Columns 15-16, Rows 6-24
        for y in range(6, 25):
            for x in [15, 16]:
                plateau_tiles.add((x, y))

        # Main plateau lower vertical section: Columns 11-14, Rows 16-24
        for y in range(16, 25):
            for x in range(11, 15):
                plateau_tiles.add((x, y))

        # Eastern plateau extension: Columns 17-21, Rows 14-16
        for y in range(14, 17):
            for x in range(17, 23): # Include 22
                plateau_tiles.add((x, y))

        # Western plateau extension: Columns 6-10, Rows 18-19
        for y in range(18, 20):
            for x in range(6, 11):
                plateau_tiles.add((x, y))

        # Northern horizontal plateau section: Columns 11-17, Rows 6-10
        for y in range(6, 11):
            for x in range(11, 18):
                plateau_tiles.add((x, y))

        # Include staircase tiles on level 1 to prevent being blocked by the plateau check
        plateau_tiles.add((6, 19))
        plateau_tiles.add((21, 17))
        plateau_tiles.add((17, 9)) # Add (17, 9) to plateau_tiles

        # Blocked plateau tiles (solid TYPE_2889 walls on plateau)
        blocked_plateau = set([
            (11, 9), (12, 9), (13, 9), (14, 10), (17, 10), (17, 11), (17, 12), (17, 13),
            (17, 17), (17, 18), (18, 17), (19, 17), (20, 17)
        ])

        # Impassable ground level obstacles
        for y in [14, 15]:
            impassable_ground.add((1, y))
        impassable_ground.add((0, 16))

        # COMPLETE LAKE / CENTRAL POND DEFINITION (Rows 10-13, Columns 2-10 are water)
        for x in range(2, 11):
            for y in range(10, 14):
                impassable_ground.add((x, y))

        for x in [24, 25]:
            for y in [0, 1, 2]:
                impassable_ground.add((x, y))

        # CORRECTED: Block Column 24 on Rows 1-13 (using range(1, 14) to include 13)
        for y in range(1, 14):
            impassable_ground.add((24, y))

        for x in range(11, 16):
            impassable_ground.add((x, 25))
        for x in range(18, 30):
            impassable_ground.add((x, 25))

        # Ground level solid cliff faces on Row 17 (except Column 23 which is covered above)
        for x in [17, 18, 19, 20, 22]:
            impassable_ground.add((x, 17))

        # Ground level solid cliff faces on Column 23 (Rows 14-16)
        for y in [14, 15, 16]:
            impassable_ground.add((23, y))

        # Solid item/Pokeball at (19, 7)
        impassable_ground.add((19, 7))

        # Adjacent-tile stair transitions:
        stairs[(21, 17, 1)] = (21, 18, 0)
        stairs[(21, 18, 0)] = (21, 17, 1)
        stairs[(6, 19, 1)] = (6, 20, 0)
        stairs[(6, 20, 0)] = (6, 19, 1)
        stairs[(17, 9, 1)] = (18, 9, 0)
        stairs[(18, 9, 0)] = (17, 9, 1)

    elif map_id == "0_220": # Safari Zone Center
        for x in range(8, 22):
            for y in range(8, 14):
                impassable_ground.add((x, y))
        for x in range(2, 18):
            for y in [15, 16]:
                impassable_ground.add((x, y))
        for x in range(22, 28):
            impassable_ground.add((x, 9))
        impassable_ground.add((28, 9))
        impassable_ground.add((29, 9))
        for x in [13, 14]:
            impassable_ground.add((x, 22))
        impassable_ground.add((15, 24))

    start_level = 1 if (start_x, start_y) in plateau_tiles else 0
    target_level = 1 if (target_x, target_y) in plateau_tiles else 0

    queue = collections.deque([(start_x, start_y, start_level, [])])
    visited = set([(start_x, start_y, start_level)])

    while queue:
        cx, cy, clevel, path = queue.popleft()
        if (cx, cy, clevel) == (target_x, target_y, target_level):
            return path

        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy
            if not (0 <= nx < width and 0 <= ny < height):
                continue
            if (cx, cy, clevel) in stairs:
                snx, sny, slevel = stairs[(cx, cy, clevel)]
                if (nx, ny) == (snx, sny):
                    nlevel = slevel
                    if (nx, ny, nlevel) not in visited:
                        visited.add((nx, ny, nlevel))
                        queue.append((nx, ny, nlevel, path + [move]))
                    continue

            nlevel = clevel
            if nlevel == 1:
                if (nx, ny) not in plateau_tiles or (nx, ny) in blocked_plateau:
                    continue
            else:
                if (nx, ny) in plateau_tiles or ((nx, ny) in impassable_ground and (nx, ny) != (target_x, target_y)):
                    continue

            if (nx, ny, nlevel) not in visited:
                visited.add((nx, ny, nlevel))
                queue.append((nx, ny, nlevel, path + [move]))

    return None

path = find_path()
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
